package com.hospital.dao;
import com.hospital.util.DBConnection;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class ReportDAO {
 public List<String> activity(LocalDate from,LocalDate through)throws SQLException{String q="SELECT DATE(start_at) AS day,status,COUNT(*) AS total FROM appointments WHERE start_at>=? AND start_at<? GROUP BY DATE(start_at),status ORDER BY day,status";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setTimestamp(1,Timestamp.valueOf(from.atStartOfDay()));p.setTimestamp(2,Timestamp.valueOf(through.plusDays(1).atStartOfDay()));try(ResultSet r=p.executeQuery()){List<String>x=new ArrayList<>();while(r.next())x.add(r.getDate("day")+" | "+r.getString("status")+" | "+r.getLong("total"));return x;}}}
 public List<String> billing(LocalDate from,LocalDate through)throws SQLException{String q="SELECT DATE(paid_at) AS day,SUM(amount) AS received,COUNT(*) AS payments FROM payments WHERE status='RECORDED' AND paid_at>=? AND paid_at<? GROUP BY DATE(paid_at) ORDER BY day";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setTimestamp(1,Timestamp.valueOf(from.atStartOfDay()));p.setTimestamp(2,Timestamp.valueOf(through.plusDays(1).atStartOfDay()));try(ResultSet r=p.executeQuery()){List<String>x=new ArrayList<>();while(r.next())x.add(r.getDate("day")+" | received "+r.getBigDecimal("received")+" | payments "+r.getLong("payments"));return x;}}}
 public String patientCounts()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) total,SUM(active) active FROM patients");ResultSet r=p.executeQuery()){r.next();return "Patients total="+r.getLong("total")+", active="+r.getLong("active");}}
}
